const people=['RA','ZS','JH','MH','CF','MM','PH','JP','JC','DA'];const colors=['#f398ce','#c2a2f1','#ffc2b0','#a3efc3','#a5d7ff','#d9a1ef','#fff09c','#b5b3fc','#ffa9c4','#92f0d1'];const players=document.querySelector('#players');people.forEach((name,i)=>{const b=document.createElement('button');b.className='player'+(i===0?' selected':'');b.style.setProperty('--color',colors[i]);b.dataset.player=name;b.setAttribute('aria-label',name+(i===0?', birthday player':', player '+(i+1)));b.innerHTML=`<span class="number">P${i+1}</span><span class="initial">${name}</span>`;const slot=document.createElement("div");slot.className="player-slot";slot.append(b);if(i===0){const label=document.createElement("span");label.className="birthday-tag";label.textContent="BIRTHDAY PLAYER";b.append(label)}players.append(slot)});const dates=document.querySelector('#dates');for(let i=1;i<=30;i++){let b=document.createElement('button');b.textContent=i;b.setAttribute('aria-label',`November ${i}, 2026`);if(i>=20&&i<=22)b.className='weekend';b.onclick=()=>{if(i>=20&&i<=22)showDay(['friday','saturday','sunday'][i-20]);else{document.querySelector('#day-note').hidden=false;document.querySelector('#day-note').textContent='The birthday weekend is November 20–22.'}};dates.append(b)}
